import{_ as e,o as d,c as a,a2 as o}from"./chunks/framework.DrWxItG4.js";const b=JSON.parse('{"title":"Tile extras","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tile-extras.md","filePath":"guide/tile-extras.md"}'),r={name:"guide/tile-extras.md"};function n(i,t,h,s,l,c){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="tile-extras" tabindex="-1">Tile extras <a class="header-anchor" href="#tile-extras" aria-label="Permalink to &quot;Tile extras&quot;">​</a></h1><p>A tile whose flags have bit <code>0x01</code> carries extra data after its record (see <a href="/gtps-guide/guide/world-data">World data</a>): a <code>u8</code> type, then that type&#39;s bytes. This page lists every type the 5.60 client&#39;s parser (<code>TileExtra_Serialize</code>, <code>0x15ce080</code>) knows, in the direction the client reads them from the server (<a href="/gtps-guide/packets/04-send-map-data">SEND_MAP_DATA 0x04</a> and <a href="/gtps-guide/packets/05-send-tile-update-data">SEND_TILE_UPDATE_DATA 0x05</a>).</p><ul><li>Which type a tile uses comes from its foreground item&#39;s <strong>action type</strong> in items.dat (<code>0x15d1014</code>, run when the foreground is set). If the server sends a type that doesn&#39;t match, the client reads the wrong bytes and the rest of the world is garbage.</li><li>Some fields exist only in the client&#39;s own saved copy of a world. They are marked <strong>not sent by the server</strong>; don&#39;t send them.</li><li>After the type&#39;s own bytes, items with a certain item flag have a common trailer. It is described on <a href="/gtps-guide/guide/world-data">World data</a>.</li><li>Numbers are little-endian. Strings are <code>u16 length</code> + bytes, with no terminator.</li></ul><table tabindex="0"><thead><tr><th>Type</th><th>Name</th></tr></thead><tbody><tr><td><a href="#0x01">0x01</a></td><td>Door</td></tr><tr><td><a href="#0x02">0x02</a></td><td>Sign</td></tr><tr><td><a href="#0x03">0x03</a></td><td>Lock</td></tr><tr><td><a href="#0x04">0x04</a></td><td>Seed</td></tr><tr><td><a href="#0x05">0x05</a></td><td>(no data)</td></tr><tr><td><a href="#0x06">0x06</a></td><td>Mailbox</td></tr><tr><td><a href="#0x07">0x07</a></td><td>Bulletin board</td></tr><tr><td><a href="#0x08">0x08</a></td><td>Dice block</td></tr><tr><td><a href="#0x09">0x09</a></td><td>Provider</td></tr><tr><td><a href="#0x0a">0x0a</a></td><td>Achievement block</td></tr><tr><td><a href="#0x0b">0x0b</a></td><td>Heart monitor</td></tr><tr><td><a href="#0x0c">0x0c</a></td><td>Donation box</td></tr><tr><td><a href="#0x0d">0x0d</a></td><td>(mailbox layout)</td></tr><tr><td><a href="#0x0e">0x0e</a></td><td>Mannequin</td></tr><tr><td><a href="#0x0f">0x0f</a></td><td>Bunny egg</td></tr><tr><td><a href="#0x10">0x10</a></td><td>Game block</td></tr><tr><td><a href="#0x11">0x11</a></td><td>Game generator</td></tr><tr><td><a href="#0x12">0x12</a></td><td>Xenonite crystal</td></tr><tr><td><a href="#0x13">0x13</a></td><td>Phone booth</td></tr><tr><td><a href="#0x14">0x14</a></td><td>Crystal</td></tr><tr><td><a href="#0x15">0x15</a></td><td>Crime in progress</td></tr><tr><td><a href="#0x16">0x16</a></td><td>Spotlight</td></tr><tr><td><a href="#0x17">0x17</a></td><td>Display block</td></tr><tr><td><a href="#0x18">0x18</a></td><td>Vending machine</td></tr><tr><td><a href="#0x19">0x19</a></td><td>Fish tank port</td></tr><tr><td><a href="#0x1a">0x1a</a></td><td>Solar collector</td></tr><tr><td><a href="#0x1b">0x1b</a></td><td>Forge</td></tr><tr><td><a href="#0x1c">0x1c</a></td><td>Giving Tree</td></tr><tr><td><a href="#0x1d">0x1d</a></td><td>Giving Tree Stump</td></tr><tr><td><a href="#0x1e">0x1e</a></td><td>Steam Organ</td></tr><tr><td><a href="#0x1f">0x1f</a></td><td>Silkworm</td></tr><tr><td><a href="#0x20">0x20</a></td><td>Sewing Machine</td></tr><tr><td><a href="#0x21">0x21</a></td><td>Country Flag / Challenge flags</td></tr><tr><td><a href="#0x22">0x22</a></td><td>Lobster Trap</td></tr><tr><td><a href="#0x23">0x23</a></td><td>Painting Easel</td></tr><tr><td><a href="#0x24">0x24</a></td><td>Battle Pet Cage</td></tr><tr><td><a href="#0x25">0x25</a></td><td>Pet Trainer</td></tr><tr><td><a href="#0x26">0x26</a></td><td>Steam Engine</td></tr><tr><td><a href="#0x27">0x27</a></td><td>Lock-Bot</td></tr><tr><td><a href="#0x28">0x28</a></td><td>Weather Machine (one setting)</td></tr><tr><td><a href="#0x29">0x29</a></td><td>Spirit Storage Unit</td></tr><tr><td><a href="#0x2a">0x2a</a></td><td>Data Bedrock</td></tr><tr><td><a href="#0x2b">0x2b</a></td><td>Display Shelf</td></tr><tr><td><a href="#0x2c">0x2c</a></td><td>VIP Entrance</td></tr><tr><td><a href="#0x2d">0x2d</a></td><td>Challenge Timer</td></tr><tr><td><a href="#0x2e">0x2e</a></td><td>(unused)</td></tr><tr><td><a href="#0x2f">0x2f</a></td><td>Fish Wall Mount</td></tr><tr><td><a href="#0x30">0x30</a></td><td>Portrait</td></tr><tr><td><a href="#0x31">0x31</a></td><td>Weather Machine (several settings)</td></tr><tr><td><a href="#0x32">0x32</a></td><td>Fossil Prep Station</td></tr><tr><td><a href="#0x33">0x33</a></td><td>DNA Processor</td></tr><tr><td><a href="#0x34">0x34</a></td><td>Howler / Trickster</td></tr><tr><td><a href="#0x35">0x35</a></td><td>Chemsynth Tank</td></tr><tr><td><a href="#0x36">0x36</a></td><td>Storage box</td></tr><tr><td><a href="#0x37">0x37</a></td><td>Oven</td></tr><tr><td><a href="#0x38">0x38</a></td><td>Audio Rack</td></tr><tr><td><a href="#0x39">0x39</a></td><td>Geiger Charger</td></tr><tr><td><a href="#0x3a">0x3a</a></td><td>Adventure Begins</td></tr><tr><td><a href="#0x3b">0x3b</a></td><td>Tomb Robber</td></tr><tr><td><a href="#0x3c">0x3c</a></td><td>Faction block</td></tr><tr><td><a href="#0x3d">0x3d</a></td><td>Training Port</td></tr><tr><td><a href="#0x3e">0x3e</a></td><td>Item Sucker (MAGPLANT)</td></tr><tr><td><a href="#0x3f">0x3f</a></td><td>Robot</td></tr><tr><td><a href="#0x40">0x40</a></td><td>Lucky Token</td></tr><tr><td><a href="#0x41">0x41</a></td><td>(no data)</td></tr><tr><td><a href="#0x42">0x42</a></td><td>GrowScan 9000</td></tr><tr><td><a href="#0x43">0x43</a></td><td>Containment Field Power Node</td></tr><tr><td><a href="#0x44">0x44</a></td><td>Spirit Board</td></tr><tr><td><a href="#0x45">0x45</a></td><td>Tesseract Manipulator</td></tr><tr><td><a href="#0x46">0x46</a></td><td>Heart of Gaia</td></tr><tr><td><a href="#0x47">0x47</a></td><td>Techno-Organic Engine</td></tr><tr><td><a href="#0x48">0x48</a></td><td>Storm Cloud</td></tr><tr><td><a href="#0x49">0x49</a></td><td>Phased block</td></tr><tr><td><a href="#0x4a">0x4a</a></td><td>Safe Vault</td></tr><tr><td><a href="#0x4b">0x4b</a></td><td>Angelic Counting Cloud</td></tr><tr><td><a href="#0x4c">0x4c</a></td><td>PvE NPC</td></tr><tr><td><a href="#0x4d">0x4d</a></td><td>Infinity Weather Machine</td></tr><tr><td><a href="#0x4e">0x4e</a></td><td>Completionist</td></tr><tr><td><a href="#0x4f">0x4f</a></td><td>Feeding block</td></tr><tr><td><a href="#0x50">0x50</a></td><td>Kranken&#39;s block</td></tr><tr><td><a href="#0x51">0x51</a></td><td>Friends Entrance</td></tr><tr><td><a href="#0x52">0x52</a></td><td>(no data)</td></tr></tbody></table><h2 id="0x01" tabindex="-1">0x01 Door <a class="header-anchor" href="#0x01" aria-label="Permalink to &quot;0x01 Door {#0x01}&quot;">​</a></h2><p>Doors, the Main Door, portals and the Sungate: items with action type 2 (Door), 13 (Main Door), 26 (Portal) and 43 (Sungate). Created by <code>0x15d1014</code> for those action types.</p><p>From the server (the 0x04 world load and 0x05 tile updates both pass &quot;from server&quot;):</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u16 len + bytes</td><td>label</td><td>the text shown over the door (extra+0x28)</td></tr><tr><td>u8</td><td>flags</td><td>extra+9. Bit 3 (0x08): locked. The client then checks whether you may use it (<code>0x15b2a80</code>) and shows <code> `w&lt;Locked&gt;</code> `` instead of the label if you may not</td></tr></tbody></table><p>Not sent by the server: the client&#39;s own saved copy has three strings instead of one: extra+0x10, +0x28 (label), +0x40, then the u8. +0x10 is shown in place of the label when it isn&#39;t empty, so it is probably the destination (<code>WORLD:ID</code>) and +0x40 the door&#39;s id.</p><ul><li>The label is drawn by the tile-info code (<code>0x13002b4</code>). Item 9358 (0x248e) never shows its label.</li><li>When the client writes a door that came from a server (only for its local copy) and the item isn&#39;t Gateway To Adventure (1682), Mystery Door (4718) or Mystery Portal (11136), it writes the destination if it has one, cut at <code>:</code>.</li></ul><p><small>Read by <code>0x15ce080</code> case 1 (falls through to the u8 of case 0x42); shown by <code>0x13002b4</code>.</small></p><h2 id="0x02" tabindex="-1">0x02 Sign <a class="header-anchor" href="#0x02" aria-label="Permalink to &quot;0x02 Sign {#0x02}&quot;">​</a></h2><p>Signs, tombstones, banners and markers: item action type 10. Created by <code>0x15d1014</code>.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u16 len + bytes</td><td>text</td><td>the sign&#39;s text (extra+0x28), shown in a bubble by the tile-info code (<code>0x13002b4</code>, through <code>0x15b1de8</code>)</td></tr><tr><td>u32</td><td>value</td><td>extra+0xc. Not read by the sign display; gurotopia sends <code>-1</code>. Its meaning wasn&#39;t traced</td></tr></tbody></table><p>For seven items the text goes to extra+0x40 instead and isn&#39;t shown as a sign: Path Marker (1684), Carnival Landing (1912), Gruesome Marker (4446), Objective Marker (4482), Hospital Chair (14678), Fashion Show Bouncer (15598) and Fashion Show Voting Box (15600) (<code>0x15b17d0</code>). For those it is probably an id the item uses.</p><p>When the client writes a sign it filters the text first (<code>0x1585028</code>).</p><p><small>Read by <code>0x15ce080</code> case 2.</small></p><h2 id="0x03" tabindex="-1">0x03 Lock <a class="header-anchor" href="#0x03" aria-label="Permalink to &quot;0x03 Lock {#0x03}&quot;">​</a></h2><p>Every lock (Small/Big/Huge Lock, World Lock, Diamond Lock, Guild Lock, ...): item action type 3. Created by <code>0x15d1014</code>.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u8</td><td>flags</td><td>extra+9: the lock&#39;s settings bits</td></tr><tr><td>u32</td><td>owner</td><td>extra+0xc: the owner&#39;s user id</td></tr><tr><td>u32</td><td>count</td><td>number of entries that follow</td></tr><tr><td>u32 × count</td><td>access</td><td>extra+0x80: user ids with access</td></tr><tr><td>u32</td><td>(world version ≥ 12)</td><td>extra+0x138; meaning not traced</td></tr><tr><td>u32</td><td>(world version ≥ 13)</td><td>extra+0x13c; meaning not traced</td></tr></tbody></table><p>The world version is the <code>u16</code> at the start of the world data (world+2). A tile update (0x05) uses the version of the world that is loaded.</p><ul><li>Changing a tile away from its lock removes the lock&#39;s area (<code>0x15aef40</code> → <code>0x1625994</code>).</li><li>The Guild Lock (5814) is followed by the guild block described in the common trailer, without its first u8.</li></ul><p><small>Read by <code>0x15ce080</code> case 3.</small></p><h2 id="0x04" tabindex="-1">0x04 Seed <a class="header-anchor" href="#0x04" aria-label="Permalink to &quot;0x04 Seed {#0x04}&quot;">​</a></h2><p>A planted tree: item action type 19 (seeds). Created by <code>0x15d1014</code> with the age 0 and 3 fruit.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>age</td><td>extra+0x5c: seconds since it was planted. The client keeps counting from here</td></tr><tr><td>u8</td><td>fruit</td><td>extra+0x60: how many fruit the tree has</td></tr></tbody></table><ul><li>The client adds the seconds that pass to the age by itself (<code>0x15d0b24</code>, run before every serialize and by <code>0x15d1a64</code>).</li><li>The tile text (<code>0x15b2604</code>) shows the time left, the seed item&#39;s grow time (item+0xc4) minus the age, as &quot;... to harvest&quot;, or <code> `w(Punch to harvest)</code> `` when it is ready.</li></ul><p><small>Read by <code>0x15ce080</code> case 4 (<code>switchD…caseD_4</code>).</small></p><h2 id="0x05" tabindex="-1">0x05 (no data) <a class="header-anchor" href="#0x05" aria-label="Permalink to &quot;0x05 (no data) {#0x05}&quot;">​</a></h2><p>Created by <code>0x15d1014</code> for item action type 30, with extra+9 = 2. No item in the 5.60 items.dat has that action type.</p><p>The switch in <code>0x15ce080</code> has no case for 5, so it carries no bytes of its own (only the common trailer, if the item&#39;s flag asks for it).</p><h2 id="0x06" tabindex="-1">0x06 Mailbox <a class="header-anchor" href="#0x06" aria-label="Permalink to &quot;0x06 Mailbox {#0x06}&quot;">​</a></h2><p>Mailbox, Blue Mailbox, Hacker&#39;s Dialog, Message in a Bottle, Message in a Diamond Bottle: item action type 33.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u16 len + bytes</td><td>string 1</td><td>extra+0x10</td></tr><tr><td>u16 len + bytes</td><td>string 2</td><td>extra+0x28</td></tr><tr><td>u16 len + bytes</td><td>string 3</td><td>extra+0x40</td></tr><tr><td>u8</td><td>flag</td><td>extra+9</td></tr></tbody></table><p>The same four fields are read for every type that shares this code (6, 7, 0x0c, 0x0d). Reading also clears extra+0x58. The tile code in this range doesn&#39;t read the strings; they are probably filled only for the owner, and the byte probably tells whether something is inside (neither was traced).</p><p><small>Read by <code>0x15ce080</code> case 6 (shared with 7, 0x0c, 0x0d).</small></p><h2 id="0x07" tabindex="-1">0x07 Bulletin board <a class="header-anchor" href="#0x07" aria-label="Permalink to &quot;0x07 Bulletin board {#0x07}&quot;">​</a></h2><p>Bulletin Board, Letter, Guestbook, Scroll Bulletin, Retinal Scan Data Repository (action type 34), and the Security Camera, Starship Security Camera and Pigeon (action type 50; created with extra+9 = 8).</p><p>Same layout as <a href="#0x06">0x06</a>: three strings (extra+0x10, +0x28, +0x40) and a u8 (extra+9).</p><h2 id="0x08" tabindex="-1">0x08 Dice block <a class="header-anchor" href="#0x08" aria-label="Permalink to &quot;0x08 Dice block {#0x08}&quot;">​</a></h2><p>Dice Block and Roshambo Block: item action type 36.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u8</td><td>value</td><td>extra+0x60: probably the face shown (the dice roll itself comes in TILE_APPLY_DAMAGE, 0x08)</td></tr></tbody></table><p><small>Read by <code>0x15ce080</code> case 8 (<code>switchD…caseD_8</code>, shared with 0x10).</small></p><h2 id="0x09" tabindex="-1">0x09 Provider <a class="header-anchor" href="#0x09" aria-label="Permalink to &quot;0x09 Provider {#0x09}&quot;">​</a></h2><p>Things that produce an item over time (Cow, Chicken, ATM Machine, Science Station, Coffee Maker, Well, Tackle Box, ...): item action type 38.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>age</td><td>extra+0x5c: seconds since it was last collected; the client keeps counting</td></tr><tr><td>u32</td><td>(only some items)</td><td>extra+100, read only for the Winterfest Calendar - 2017 (5318), and for the Well of Love (10656) when the world version is above 16</td></tr></tbody></table><ul><li>The tile text (<code>0x15b45d0</code>) shows &quot;Ready in ...&quot; (the item&#39;s grow time, item+0xc4, minus the age) or &quot;(`wPunch to collect``)&quot;.</li><li>For the Well of Love it compares extra+100 with the grow time / 60 and shows &quot;(n/m)&quot;, so that value is probably how many times it has been used.</li></ul><p><small>Read by <code>0x15ce080</code> case 9.</small></p><h2 id="0x0a" tabindex="-1">0x0a Achievement block <a class="header-anchor" href="#0x0a" aria-label="Permalink to &quot;0x0a Achievement block {#0x0a}&quot;">​</a></h2><p>The Achievement Block (982): item action type 40. Created with extra+0x60 = 0x7f.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>value</td><td>extra+0xc (0 when created); probably the user id of the player whose achievement it shows (not traced)</td></tr><tr><td>u8</td><td>achievement</td><td>extra+0x60: the icon drawn. 0–127 picks a frame of <code>game/amorkolg.rttex</code>, a negative value a frame of <code>game/amorkasd.rttex</code> (renderer <code>0x11a9ee4</code>)</td></tr></tbody></table><p><small>Read by <code>0x15ce080</code> case 0x0a (u32, then the u8 of <code>caseD_8</code>).</small></p><h2 id="0x0b" tabindex="-1">0x0b Heart monitor <a class="header-anchor" href="#0x0b" aria-label="Permalink to &quot;0x0b Heart monitor {#0x0b}&quot;">​</a></h2><p>The Heart Monitor (1240): item action type 46.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>user</td><td>extra+0xc: probably the user id of the player it tracks</td></tr><tr><td>u16 len + bytes</td><td>name</td><td>extra+0x28: the player&#39;s name</td></tr></tbody></table><p>The tile text shows the name and <code>Status: Online</code>, or <code> `4Offline</code> ``. Online comes from the tile&#39;s &quot;on&quot; flag (tile flags 0x40), not from the extra data.</p><p><small>Read by <code>0x15ce080</code> case 0x0b (u32, then the string of case 0x40); shown by <code>0x13002b4</code>.</small></p><h2 id="0x0c" tabindex="-1">0x0c Donation box <a class="header-anchor" href="#0x0c" aria-label="Permalink to &quot;0x0c Donation box {#0x0c}&quot;">​</a></h2><p>Holiday Gift Box, Donation Box, Donut Donation Box: item action type 47.</p><p>Same layout as <a href="#0x06">0x06</a>: three strings (extra+0x10, +0x28, +0x40) and a u8 (extra+9).</p><h2 id="0x0d" tabindex="-1">0x0d (mailbox layout) <a class="header-anchor" href="#0x0d" aria-label="Permalink to &quot;0x0d (mailbox layout) {#0x0d}&quot;">​</a></h2><p>Created for item action type 48. No item in the 5.60 items.dat has that action type.</p><p>Same layout as <a href="#0x06">0x06</a>: three strings and a u8.</p><h2 id="0x0e" tabindex="-1">0x0e Mannequin <a class="header-anchor" href="#0x0e" aria-label="Permalink to &quot;0x0e Mannequin {#0x0e}&quot;">​</a></h2><p>Mannequins (Mannequin, Holographic Mannequin, Snowtopian, the OMG/SAD/LOL/TROLL Mannequins, Shiny, Pearl and Diamond Mannequin, Sandtopian): item action type 49. Created with an <code>AvatarData</code> object (extra+0x98) that holds the clothes.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u16 len + bytes</td><td>label</td><td>extra+0x28: text, shown like a sign&#39;s (<code>0x15b1de8</code> treats types 2 and 0x0e as signs)</td></tr><tr><td>u8</td><td>flag</td><td>extra+9</td></tr><tr><td>u32</td><td>value</td><td>extra+0x58</td></tr><tr><td>u16 × 9</td><td>clothes</td><td>item ids of the 9 clothing slots, copied into the AvatarData (+0x14), probably in the <a href="/gtps-guide/functions/OnSetClothing">OnSetClothing</a> order (hair, shirt, legs, feet, face, hand, back, head, charm). The tint is set to <code>0xb4b4b4ff</code></td></tr><tr><td>u32, u32</td><td>(only if a slot holds Will of the Wild (5712) or Golem&#39;s Gift (10044), world version ≥ 4)</td><td>ORed into AvatarData+0x28 and +0x2c; probably those items&#39; extra state bits</td></tr></tbody></table><p>The renderer (<code>0x11a9ee4</code>) draws the AvatarData on the tile.</p><p><small>Read by <code>0x15ce080</code> case 0x0e; AvatarData setters <code>0x14ce8f8</code>, <code>0x14ce85c</code>.</small></p><h2 id="0x0f" tabindex="-1">0x0f Bunny egg <a class="header-anchor" href="#0x0f" aria-label="Permalink to &quot;0x0f Bunny egg {#0x0f}&quot;">​</a></h2><p>The Bunny Egg (610): item action type 51.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>count</td><td>extra+0x5c. The client doesn&#39;t age this type (<code>0x15d0b24</code> skips it), so it is a plain counter, probably the eggs put in</td></tr></tbody></table><p>Types 0x1b, 0x26, 0x27, 0x32 and 0x39 share this one-u32 code.</p><p><small>Read by <code>0x15ce080</code> case 0x0f (<code>switchD…caseD_f</code>).</small></p><h2 id="0x10" tabindex="-1">0x10 Game block <a class="header-anchor" href="#0x10" aria-label="Permalink to &quot;0x10 Game block {#0x10}&quot;">​</a></h2><p>The team items of the game blocks (Staging Platform, Game Block, Game Flag, Game Grave, Game Goal, Game Egg, ...): item action type 52. Created with extra+0x60 = 4.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u8</td><td>team</td><td>extra+0x60: the team the block belongs to. The touch code compares it with the player&#39;s team (avatar+0x26d) to decide whether the flag, goal or grave reacts. 4 (the default) is probably &quot;no team&quot;</td></tr></tbody></table><p>Same code as <a href="#0x08">0x08</a>.</p><p><small>Read by <code>0x15ce080</code> case 0x10; compared in <code>0x13002b4</code>.</small></p><h2 id="0x11" tabindex="-1">0x11 Game generator <a class="header-anchor" href="#0x11" aria-label="Permalink to &quot;0x11 Game generator {#0x11}&quot;">​</a></h2><p>The Game Generator (1660): item action type 53.</p><p>The switch in <code>0x15ce080</code> has no case for 0x11, so it carries no bytes of its own.</p><h2 id="0x12" tabindex="-1">0x12 Xenonite crystal <a class="header-anchor" href="#0x12" aria-label="Permalink to &quot;0x12 Xenonite crystal {#0x12}&quot;">​</a></h2><p>The Xenonite Crystal (2072): item action type 54.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u8</td><td>flags</td><td>extra+9: probably the effects it turns on in the world (not traced)</td></tr><tr><td>u32</td><td>value</td><td>extra+0x5c. Not aged by the client</td></tr></tbody></table><p>Type 0x1a reads the same way.</p><p><small>Read by <code>0x15ce080</code> case 0x12.</small></p><h2 id="0x13" tabindex="-1">0x13 Phone booth <a class="header-anchor" href="#0x13" aria-label="Permalink to &quot;0x13 Phone booth {#0x13}&quot;">​</a></h2><p>Phone Booth (2208) and Transmutabooth (9170): item action type 55.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u16 × 9</td><td>clothes</td><td>9 item ids, as in <a href="#0x0e">0x0e</a>. They are copied only if the extra has an AvatarData, which <code>0x15d1014</code> creates only for mannequins, so for these items the 18 bytes are skipped</td></tr></tbody></table><p>Reading also stores the current tick in extra+0x58.</p><p><small>Read by <code>0x15ce080</code> case 0x13.</small></p><h2 id="0x14" tabindex="-1">0x14 Crystal <a class="header-anchor" href="#0x14" aria-label="Permalink to &quot;0x14 Crystal {#0x14}&quot;">​</a></h2><p>The Red, Green, Blue, White and Black Crystal: item action type 56.</p><p>From the server:</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u16 len + bytes</td><td>text</td><td>extra+0x10; probably the crystal sequence (not traced)</td></tr></tbody></table><p>Not sent by the server: only the client&#39;s saved copy adds the u32 count + u32 list of type 0x20.</p><p><small>Read by <code>0x15ce080</code> case 0x14 (then case 0x33, which reads nothing from a server).</small></p><h2 id="0x15" tabindex="-1">0x15 Crime in progress <a class="header-anchor" href="#0x15" aria-label="Permalink to &quot;0x15 Crime in progress {#0x15}&quot;">​</a></h2><p>Crime In Progress (2302): item action type 57.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u16 len + bytes</td><td>text</td><td>extra+0x10; probably the villain&#39;s name (not traced)</td></tr><tr><td>u32</td><td>age</td><td>extra+0x5c: seconds; the client keeps counting</td></tr><tr><td>u8</td><td>value</td><td>extra+0x60</td></tr></tbody></table><p>Reading clears extra+0xc. The tile-info code shows something for this type (or for item 3528) through <code>0x15b1e40</code>.</p><p><small>Read by <code>0x15ce080</code> case 0x15 (the string, then <code>caseD_4</code>, like a seed).</small></p><h2 id="0x16" tabindex="-1">0x16 Spotlight <a class="header-anchor" href="#0x16" aria-label="Permalink to &quot;0x16 Spotlight {#0x16}&quot;">​</a></h2><p>The Spotlight (2646): item action type 59.</p><p>No bytes. Reading only clears extra+0xc.</p><p><small><code>0x15ce080</code> case 0x16.</small></p><h2 id="0x17" tabindex="-1">0x17 Display block <a class="header-anchor" href="#0x17" aria-label="Permalink to &quot;0x17 Display block {#0x17}&quot;">​</a></h2><p>The Display Block (2946): item action type 61.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>item</td><td>extra+0xc: the item shown in the block. The renderer draws that item&#39;s icon on it (<code>0x11a9ee4</code>, item 0xb82)</td></tr></tbody></table><p>Reading clears extra+0x58.</p><p><small>Read by <code>0x15ce080</code> case 0x17.</small></p><h2 id="0x18" tabindex="-1">0x18 Vending machine <a class="header-anchor" href="#0x18" aria-label="Permalink to &quot;0x18 Vending machine {#0x18}&quot;">​</a></h2><p>Vending Machine (2978) and DigiVend Machine (9268): item action type 62.</p><p>From the server:</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>item</td><td>extra+0x58: the item for sale, 0 if none</td></tr><tr><td>i32</td><td>price</td><td>extra+0xc. Above 0: World Locks per item. Below 0: that many items per World Lock</td></tr></tbody></table><p>Not sent by the server: the client&#39;s saved copy adds a u32 stock (extra+0x5c) and a u32 (extra+100, probably the World Locks earned), and turns tile flags 0x40 and 0x200 on or off from them. When it writes a machine whose items-per-lock is more than its stock, it writes item 0.</p><p>The tile text (<code>0x13002b4</code>) shows <code>Selling </code>2&lt;item&gt;<code>` ... ` World Locks each` or ` per World Lock`, or</code> `wOUT OF ORDER<code></code> when the item or price is 0. Vending Hub - Checkout Counter (9270) doesn&#39;t show it.</p><p><small>Read by <code>0x15ce080</code> case 0x18.</small></p><h2 id="0x19" tabindex="-1">0x19 Fish tank port <a class="header-anchor" href="#0x19" aria-label="Permalink to &quot;0x19 Fish tank port {#0x19}&quot;">​</a></h2><p>The Fish Tank Port (3002): item action type 63.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u8</td><td>flags</td><td>extra+9</td></tr><tr><td>u32</td><td>count</td><td>number of u32 values that follow</td></tr><tr><td>u32 × count</td><td>values</td><td>extra+0x80; probably pairs of fish item id and weight (not traced)</td></tr></tbody></table><p><small>Read by <code>0x15ce080</code> case 0x19 (u8, then the list of <code>caseD_20</code>).</small></p><h2 id="0x1a" tabindex="-1">0x1a Solar collector <a class="header-anchor" href="#0x1a" aria-label="Permalink to &quot;0x1a Solar collector {#0x1a}&quot;">​</a></h2><p>The Solar Collector (3078): item action type 65. Created with extra+9 = 0x18.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u8</td><td>mode</td><td>extra+9: bits 0x08 and 0x10 pick the text &quot;Only works when planting&quot;, &quot;Only works when splicing&quot; or &quot;Disabled&quot;</td></tr><tr><td>u32</td><td>charge</td><td>extra+0x5c: seconds of charge; the client keeps counting. Full at 86400 (one day)</td></tr></tbody></table><p>The tile text (<code>0x15b4298</code>) shows <code>Solar Collector</code>, then <code>n% charged</code> (charge × 100 / 86400) or <code>Fully charged!</code>, then the mode.</p><p><small>Read by <code>0x15ce080</code> case 0x1a (same code as 0x12).</small></p><h2 id="0x1b" tabindex="-1">0x1b Forge <a class="header-anchor" href="#0x1b" aria-label="Permalink to &quot;0x1b Forge {#0x1b}&quot;">​</a></h2><p>The Forge (3194): item action type 66.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>time</td><td>extra+0x5c: seconds. Unlike most types the client counts this one <strong>down</strong> to 0 (<code>0x15d0b24</code>), so it is probably the time left on the current job</td></tr></tbody></table><p>Same code as <a href="#0x0f">0x0f</a>.</p><p><small>Read by <code>0x15ce080</code> case 0x1b.</small></p><h2 id="0x1c" tabindex="-1">0x1c Giving Tree <a class="header-anchor" href="#0x1c" aria-label="Permalink to &quot;0x1c Giving Tree {#0x1c}&quot;">​</a></h2><p>Item action type 67, the <strong>Giving Tree</strong> (3200). It grows a gift you can punch out.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u8</td><td>flags (extra+9)</td><td>bit 0: no tooltip is shown (probably &quot;already harvested&quot;)</td></tr><tr><td>u32</td><td>age (+0x5c)</td><td>seconds since planting; the client keeps adding real time to it</td></tr><tr><td>u8</td><td>decorated (+0x60)</td><td>percent decorated; shown as &quot;<code>N% Decorated</code>&quot; when non-zero</td></tr></tbody></table><ul><li>Tooltip (<code>0x15b30f4</code>): &quot;<code> `7Giving Tree</code> <code>&quot;, then &quot;`&amp;lt;time&gt; to gift!`&quot; while `item.growTime − age &gt; 0` (item+0x13c), otherwise &quot; (</code> `wPunch to nab a gift!<code></code>)&quot; if you have access to the tile.</li></ul><p><small>Read by <code>0x15ce080</code>; tooltip <code>0x15b30f4</code>; timer <code>0x15d0b24</code>.</small></p><h2 id="0x1d" tabindex="-1">0x1d Giving Tree Stump <a class="header-anchor" href="#0x1d" aria-label="Permalink to &quot;0x1d Giving Tree Stump {#0x1d}&quot;">​</a></h2><p>Item action type 68, the <strong>Giving Tree Stump</strong> (3202).</p><p>No bytes. When reading, the client starts a local timer (+0x58 = now, +0x5c = 600), which its tick function then counts up like any other age field.</p><p><small>Read by <code>0x15ce080</code>.</small></p><h2 id="0x1e" tabindex="-1">0x1e Steam Organ <a class="header-anchor" href="#0x1e" aria-label="Permalink to &quot;0x1e Steam Organ {#0x1e}&quot;">​</a></h2><p>Item action type 71, the <strong>Steam Organ</strong> (3282).</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u8</td><td>+0x60</td><td>not traced</td></tr><tr><td>u32</td><td>+0xc</td><td>not traced</td></tr></tbody></table><p>The renderer draws steam pieces (action types 69 and 71) with a frame picked from their neighbours, not from these values. No reader of the two fields was found.</p><p><small>Read by <code>0x15ce080</code>.</small></p><h2 id="0x1f" tabindex="-1">0x1f Silkworm <a class="header-anchor" href="#0x1f" aria-label="Permalink to &quot;0x1f Silkworm {#0x1f}&quot;">​</a></h2><p>Item action type 72, the <strong>Silkworm</strong> (3316). A pet that needs food and water and makes silk.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u8</td><td>flags (+9)</td><td>bit 0: dead. Bit 5 is used locally for its blink animation</td></tr><tr><td>u16 len + bytes</td><td>name (+0x10)</td><td>shown as &quot;<code> `7&lt;name&gt; the Silkworm</code> ``&quot;</td></tr><tr><td>u32</td><td>age (+0x5c)</td><td>seconds; it dies of old age after 1,728,000 s (20 days)</td></tr><tr><td>u32</td><td>silk (+0x64)</td><td>at 86,400 or more the tooltip says &quot;(Punch to collect silk)&quot;</td></tr><tr><td>u32</td><td>+0xc</td><td>probably the illness timer: counts down; while it is above 0 the tooltip says &quot;Feeling ill.&quot;</td></tr><tr><td>u8</td><td>+0x60</td><td>reset to 0 when the +0xc timer ends (probably the illness kind)</td></tr><tr><td>u32</td><td>food (+0xa8+0)</td><td>seconds of food left; starts at 21,600 (6 h)</td></tr><tr><td>u32</td><td>water (+0xa8+4)</td><td>seconds of water left; starts at 21,600</td></tr><tr><td>u32</td><td>colour (+0xa8+8)</td><td>RGBA; a new silkworm gets a random colour</td></tr><tr><td>u32</td><td>neglect (+0xa8+0xc)</td><td>seconds without food or water; above 86,400 (1 day) it dies</td></tr></tbody></table><p>The last four u32s are read <strong>only if the tile&#39;s item is a Silkworm</strong>: the 16-byte block is allocated when the foreground is set, so it is absent for any other item.</p><ul><li>The tooltip adds a status line when food or water is below about 43,300 s or above 259,200 s (3 days): probably &quot;Hungry!&quot;/&quot;Thirsty!&quot; when low and &quot;Stuffed full!&quot;/&quot;Bloated!&quot; when high (the strings are all in the tooltip function, but which test picks which wasn&#39;t pinned down).</li><li>The client ages it itself between updates (<code>0x15d0b24</code>): food and water count down, neglect counts up, silk grows after its first day. A dead worm&#39;s tooltip says &quot;R.I.P. Died at N days of old age / illness / starvation / thirst / neglect&quot;.</li></ul><p><small>Read by <code>0x15ce080</code>; tooltip <code>0x15b3bb0</code>; timer <code>0x15d0b24</code>; getters <code>0x15d1a8c</code>, <code>0x15d1acc</code>, <code>0x15d1b0c</code>; drawn by <code>0x11b220c</code>.</small></p><h2 id="0x20" tabindex="-1">0x20 Sewing Machine <a class="header-anchor" href="#0x20" aria-label="Permalink to &quot;0x20 Sewing Machine {#0x20}&quot;">​</a></h2><p>Item action type 73, the <strong>Sewing Machine</strong> (3354).</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>count</td><td>number of values</td></tr><tr><td>u32 × count</td><td>list (+0x80)</td><td>the project. Entry 0 is an item id shown as &quot;Current project:\\n&lt;item name&gt;&quot;. With more entries, entry 1 is a small number (below 7 it adds a line) and entry 2 is another item whose name is shown</td></tr></tbody></table><p>The exact meaning of entries 1 and 2 is probably the step and the next bolt; it wasn&#39;t traced further.</p><p><small>Read by <code>0x15ce080</code>; tooltip <code>0x15b4004</code>.</small></p><h2 id="0x21" tabindex="-1">0x21 Country Flag / Challenge flags <a class="header-anchor" href="#0x21" aria-label="Permalink to &quot;0x21 Country Flag / Challenge flags {#0x21}&quot;">​</a></h2><p>Item action type 74, the <strong>Country Flag</strong> (3394), and action type 86, the <strong>Challenge Start Flag</strong> (3806) and <strong>Challenge End Flag</strong> (3808).</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u16 len + bytes</td><td>country (+0x10)</td><td><strong>only if the tile is a Country Flag (3394)</strong>: the country code. The renderer draws <code>interface/flags/&lt;code&gt;.rttex</code> on it</td></tr></tbody></table><p>For the challenge flags (or any other item) a server sends <strong>no bytes</strong> for this type.</p><p><small>Read by <code>0x15ce080</code>; drawn in <code>0x11a9ee4</code>.</small></p><h2 id="0x22" tabindex="-1">0x22 Lobster Trap <a class="header-anchor" href="#0x22" aria-label="Permalink to &quot;0x22 Lobster Trap {#0x22}&quot;">​</a></h2><p>Item action type 75, the <strong>Lobster Trap</strong> (3448).</p><p>No bytes from a server. Two u32s (+0x5c, +0x64) exist only in the client&#39;s own saved copy.</p><p><small>Read by <code>0x15ce080</code>.</small></p><h2 id="0x23" tabindex="-1">0x23 Painting Easel <a class="header-anchor" href="#0x23" aria-label="Permalink to &quot;0x23 Painting Easel {#0x23}&quot;">​</a></h2><p>Item action type 76, the <strong>Painting Easel</strong> (3528).</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>+0x64</td><td>probably the painted item&#39;s id (not traced)</td></tr><tr><td>u16 len + bytes</td><td>label (+0x10)</td><td>shown in a speech bubble when you point at the easel</td></tr></tbody></table><p><small>Read by <code>0x15ce080</code>; tooltip <code>0x13002b4</code>.</small></p><h2 id="0x24" tabindex="-1">0x24 Battle Pet Cage <a class="header-anchor" href="#0x24" aria-label="Permalink to &quot;0x24 Battle Pet Cage {#0x24}&quot;">​</a></h2><p>Item action type 77, the <strong>Battle Pet Cage</strong> (3548).</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u16 len + bytes</td><td>name (+0x10)</td><td>the pet&#39;s name, shown in a speech bubble when you point at the cage</td></tr><tr><td>u32</td><td>+0x64</td><td>not traced (probably the pet or one of its abilities)</td></tr><tr><td>u32</td><td>+0x58</td><td>not traced</td></tr><tr><td>u32</td><td>+0x5c</td><td>not traced (this type has no client timer, so it isn&#39;t an age)</td></tr></tbody></table><p><small>Read by <code>0x15ce080</code>; tooltip <code>0x13002b4</code>.</small></p><h2 id="0x25" tabindex="-1">0x25 Pet Trainer <a class="header-anchor" href="#0x25" aria-label="Permalink to &quot;0x25 Pet Trainer {#0x25}&quot;">​</a></h2><p>Item action type 78: the <strong>Pet Trainer</strong> (3554), <strong>Pet Battle Gym Leader</strong> (15222) and <strong>Pet Battle Gym Trainer</strong> (15224).</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u16 len + bytes</td><td>name (+0x10)</td><td>probably the trainer&#39;s name</td></tr><tr><td>u32</td><td>count</td><td>number of list values</td></tr><tr><td>u32</td><td>+0x5c</td><td>age in seconds (counted up by the client)</td></tr><tr><td>u32 × count</td><td>list (+0x80)</td><td>probably the trainer&#39;s battle pets (item ids)</td></tr></tbody></table><p>The count comes <strong>before</strong> the +0x5c value, and the list after it. A u16 string (+0x40) follows only in the client&#39;s own saved copy (world version above 23), never from a server. New trainers are registered with the pet-battle manager (<code>0x14d1e54</code>).</p><p><small>Read by <code>0x15ce080</code>; created by <code>0x15d1014</code>.</small></p><h2 id="0x26" tabindex="-1">0x26 Steam Engine <a class="header-anchor" href="#0x26" aria-label="Permalink to &quot;0x26 Steam Engine {#0x26}&quot;">​</a></h2><p>Item action type 79, the <strong>Steam Engine</strong> (3558).</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>temperature (+0x5c)</td><td>shown as &quot;<code> `4Steam Engine</code> ``\\n<code>&amp;lt;N&gt; degrees</code>&quot;; the client lowers it by 1 each second (not below 0)</td></tr></tbody></table><p><small>Read by <code>0x15ce080</code>; tooltip <code>0x15b3728</code>; timer <code>0x15d0b24</code>.</small></p><h2 id="0x27" tabindex="-1">0x27 Lock-Bot <a class="header-anchor" href="#0x27" aria-label="Permalink to &quot;0x27 Lock-Bot {#0x27}&quot;">​</a></h2><p>Item action type 80, the <strong>Lock-Bot</strong> (3682).</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>+0x5c</td><td>seconds, counted up by the client (probably how long it has been running)</td></tr></tbody></table><p><small>Read by <code>0x15ce080</code>.</small></p><h2 id="0x28" tabindex="-1">0x28 Weather Machine (one setting) <a class="header-anchor" href="#0x28" aria-label="Permalink to &quot;0x28 Weather Machine (one setting) {#0x28}&quot;">​</a></h2><p>Item action type 81: <strong>Weather Machine - Heatwave</strong> (3694), <strong>Balloon Warz</strong> (4892), <strong>Background</strong> (5000), <strong>Valentine&#39;s</strong> (5654), <strong>St. Paddy&#39;s Day</strong> (5716), <strong>Digital Rain</strong> (6854), <strong>Black Digital Rain</strong> (15802).</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>setting (+0x64)</td><td>the machine&#39;s one setting. A new machine starts at <code>0x4080ff00</code>, so for Heatwave it&#39;s probably a colour; for Background it&#39;s probably an item id</td></tr></tbody></table><p><small>Read by <code>0x15ce080</code>; default from <code>0x15d1014</code>.</small></p><h2 id="0x29" tabindex="-1">0x29 Spirit Storage Unit <a class="header-anchor" href="#0x29" aria-label="Permalink to &quot;0x29 Spirit Storage Unit {#0x29}&quot;">​</a></h2><p>Item action type 82, the <strong>Spirit Storage Unit</strong> (3724).</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>ghosts (+0x64)</td><td>ghosts stored. The tooltip shows <code>ghosts × 5</code>% of capacity; at 21 or more it turns red and adds &quot;RISK OF EXPLOSION&quot;</td></tr></tbody></table><p><small>Read by <code>0x15ce080</code>; tooltip <code>0x15b4c90</code>.</small></p><h2 id="0x2a" tabindex="-1">0x2a Data Bedrock <a class="header-anchor" href="#0x2a" aria-label="Permalink to &quot;0x2a Data Bedrock {#0x2a}&quot;">​</a></h2><p>Item action type 15 (bedrock) when the item has tile data: <strong>Data Bedrock</strong> (3760), <strong>Data Starship Hull</strong> (6546).</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Condition</th><th>Meaning</th></tr></thead><tbody><tr><td>u8</td><td></td><td>always</td><td>read and thrown away</td></tr><tr><td>u32</td><td>+0xe0</td><td>world version &gt; 18</td><td>not traced (default 1)</td></tr><tr><td>u32</td><td>+0xe4</td><td>world version &gt; 18</td><td>not traced (default 1)</td></tr><tr><td>u32</td><td>+0xe8</td><td>world version &gt; 18</td><td>not traced (default 1)</td></tr><tr><td>u32</td><td>+0x11c</td><td>world version &gt; 19</td><td>not traced (default 0)</td></tr><tr><td>u32</td><td>+0x118</td><td>world version &gt; 19</td><td>not traced (default −1)</td></tr></tbody></table><p>Six more values (+0x60, +0xec, +0x114, +0x120, +0x13c) exist only in the client&#39;s own saved copy. For the Data Starship Hull (6546) the common trailer adds starship values; see that section.</p><p><small>Read by <code>0x15ce080</code>; defaults from <code>0x15d1014</code>.</small></p><h2 id="0x2b" tabindex="-1">0x2b Display Shelf <a class="header-anchor" href="#0x2b" aria-label="Permalink to &quot;0x2b Display Shelf {#0x2b}&quot;">​</a></h2><p>Item action type 83: <strong>Display Shelf</strong> (3794), <strong>Spooky Display Shelf</strong> (10190), <strong>Black Display Shelf</strong> (10552), <strong>Shirt Rack</strong> (14962).</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>+0x64</td><td>item shown top right</td></tr><tr><td>u32</td><td>+0xc</td><td>item shown top left</td></tr><tr><td>u32</td><td>+0x58</td><td>item shown bottom left</td></tr><tr><td>u32</td><td>+0x5c</td><td>item shown bottom right</td></tr></tbody></table><p>The renderer draws each of the four items at 35% scale in its corner, plus a faint offset copy (probably a shadow) when the detail setting (app+0xbd0) is above 0.5.</p><p><small>Read by <code>0x15ce080</code>; drawn in <code>0x11a9ee4</code> (action type 0x53).</small></p><h2 id="0x2c" tabindex="-1">0x2c VIP Entrance <a class="header-anchor" href="#0x2c" aria-label="Permalink to &quot;0x2c VIP Entrance {#0x2c}&quot;">​</a></h2><p>Item action type 84, the <strong>VIP Entrance</strong> (3798).</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u8</td><td>flags (+9)</td><td>probably like a lock&#39;s flags (for example &quot;open to everyone&quot;)</td></tr><tr><td>u32</td><td>+0xc</td><td>probably the owner&#39;s user id</td></tr><tr><td>u32</td><td>count</td><td>number of list values</td></tr><tr><td>u32 × count</td><td>list (+0x80)</td><td>probably the user ids that may enter</td></tr></tbody></table><p>It has the same layout as a lock&#39;s first fields. Its readers weren&#39;t traced.</p><p><small>Read by <code>0x15ce080</code>.</small></p><h2 id="0x2d" tabindex="-1">0x2d Challenge Timer <a class="header-anchor" href="#0x2d" aria-label="Permalink to &quot;0x2d Challenge Timer {#0x2d}&quot;">​</a></h2><p>Item action type 85, the <strong>Challenge Timer</strong> (3804).</p><p>No bytes from a server. A string, four u32s and a u8 exist only in the client&#39;s own saved copy, and +0x60 is reset to 0 on every read.</p><p><small>Read by <code>0x15ce080</code>.</small></p><h2 id="0x2e" tabindex="-1">0x2e (unused) <a class="header-anchor" href="#0x2e" aria-label="Permalink to &quot;0x2e (unused) {#0x2e}&quot;">​</a></h2><p>Not used by the 5.60 client: no <code>case</code> reads it, and no item action type creates it. The type byte is read and nothing else.</p><h2 id="0x2f" tabindex="-1">0x2f Fish Wall Mount <a class="header-anchor" href="#0x2f" aria-label="Permalink to &quot;0x2f Fish Wall Mount {#0x2f}&quot;">​</a></h2><p>Item action type 87: <strong>Fish Wall Mount</strong> (3810), <strong>Fancy Fish Wall Mount</strong> (5624), <strong>Crab Wall Mount</strong> (6328).</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u16 len + bytes</td><td>label (+0x10)</td><td>not traced (probably the catcher&#39;s name or the fish&#39;s name)</td></tr><tr><td>u32</td><td>fish (+0x64)</td><td>the item id of the mounted fish; when it isn&#39;t 0 the renderer draws it at 70% scale</td></tr><tr><td>u8</td><td>+0x60</td><td>probably the fish&#39;s weight in pounds (not traced)</td></tr></tbody></table><p><small>Read by <code>0x15ce080</code>; drawn in <code>0x11a9ee4</code> (action type 0x57).</small></p><h2 id="0x30" tabindex="-1">0x30 Portrait <a class="header-anchor" href="#0x30" aria-label="Permalink to &quot;0x30 Portrait {#0x30}&quot;">​</a></h2><p>Item action type 88: <strong>Portrait</strong> (3818), <strong>Posh Portrait</strong> (11196), <strong>Heart Portrait</strong> (15950). A painting of a player&#39;s head.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Condition</th><th>Meaning</th></tr></thead><tbody><tr><td>u16 len + bytes</td><td>label (+0x10)</td><td>always</td><td>shown in a speech bubble when you point at it</td></tr><tr><td>u32</td><td>+0x64</td><td>always</td><td>the portrait is only drawn when this isn&#39;t 0; <code>value − 1</code> goes to the drawn avatar (probably the expression)</td></tr><tr><td>u32</td><td>+0x5c</td><td>always</td><td>passed to the drawn avatar (not traced)</td></tr><tr><td>u32</td><td>+0x58</td><td>always</td><td>passed to the drawn avatar (not traced)</td></tr><tr><td>u32</td><td>skin (clothes+8)</td><td>always</td><td>probably the skin colour</td></tr><tr><td>u16</td><td>face</td><td>always</td><td>clothing slot 4</td></tr><tr><td>u16</td><td>hat</td><td>always</td><td>clothing slot 0</td></tr><tr><td>u16</td><td>hair</td><td>always</td><td>clothing slot 7</td></tr><tr><td>u32, u32</td><td>flags</td><td>world version &gt; 3, and one of the three items is 5712 (Will of the Wild) or 10044 (Golem&#39;s Gift)</td><td>OR-ed into the clothes&#39; flag words (+0x28, +0x2c), probably those items&#39; look settings</td></tr><tr><td>u32</td><td>head skin</td><td>world version &gt; 8</td><td>picks <code>game/player_head_skin&lt;N&gt;.rttex</code> (default 6)</td></tr><tr><td>u16 len + bytes</td><td>crown settings (+0x28)</td><td>world version &gt; 22, and the hat is 12958 (Infinity Crown)</td><td>the Infinity Crown&#39;s look string</td></tr></tbody></table><p>The renderer builds a small avatar from these values and draws it in the frame.</p><p><small>Read by <code>0x15ce080</code>; drawn in <code>0x11a9ee4</code> (action type 0x58); tooltip <code>0x13002b4</code>; clothes object <code>0x14ce7bc</code>.</small></p><h2 id="0x31" tabindex="-1">0x31 Weather Machine (several settings) <a class="header-anchor" href="#0x31" aria-label="Permalink to &quot;0x31 Weather Machine (several settings) {#0x31}&quot;">​</a></h2><p>Item action type 89: <strong>Weather Machine - Stuff</strong> (3832), <strong>Epoch Machine</strong> (5958), <strong>Weather Machine - Guild</strong> (6280), <strong>Concert Lights</strong> (16094), <strong>Paradise City</strong> (16406).</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>+0x64</td><td>default 2. For &quot;Stuff&quot; probably the item that falls (2 = Dirt)</td></tr><tr><td>u32</td><td>+0xc</td><td>default 50. For &quot;Stuff&quot; probably the gravity</td></tr><tr><td>u8</td><td>flags (+9)</td><td>probably option bits (for example spin or invert)</td></tr></tbody></table><p>The meanings are probably right for &quot;Stuff&quot;; the other machines reuse the fields differently, which wasn&#39;t traced.</p><p><small>Read by <code>0x15ce080</code>; defaults from <code>0x15d1014</code>.</small></p><h2 id="0x32" tabindex="-1">0x32 Fossil Prep Station <a class="header-anchor" href="#0x32" aria-label="Permalink to &quot;0x32 Fossil Prep Station {#0x32}&quot;">​</a></h2><p>Item action type 91, the <strong>Fossil Prep Station</strong> (3938).</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>+0x5c</td><td>seconds left; the client lowers it by 1 each second (not below 0). Probably the time until the fossil is prepared</td></tr></tbody></table><p><small>Read by <code>0x15ce080</code>; timer <code>0x15d0b24</code>.</small></p><h2 id="0x33" tabindex="-1">0x33 DNA Processor <a class="header-anchor" href="#0x33" aria-label="Permalink to &quot;0x33 DNA Processor {#0x33}&quot;">​</a></h2><p>Item action type 92, the <strong>DNA Processor</strong> (4080).</p><p>No bytes from a server. A u32 count plus that many u32s exist only in the client&#39;s own saved copy.</p><p><small>Read by <code>0x15ce080</code>.</small></p><h2 id="0x34" tabindex="-1">0x34 Howler / Trickster <a class="header-anchor" href="#0x34" aria-label="Permalink to &quot;0x34 Howler / Trickster {#0x34}&quot;">​</a></h2><p>Item action type 93: <strong>Howler</strong> (4344), <strong>Trickster</strong> (8020).</p><p>No bytes from a server. The client&#39;s own saved copy has a u8 (+9), a u8 (+0x60, clamped to 2–20, default 10) and a u32 (+0x64, clamped to 10–250, default 100).</p><p><small>Read by <code>0x15ce080</code>; defaults from <code>0x15d1014</code>.</small></p><h2 id="0x35" tabindex="-1">0x35 Chemsynth Tank <a class="header-anchor" href="#0x35" aria-label="Permalink to &quot;0x35 Chemsynth Tank {#0x35}&quot;">​</a></h2><p>Item action type 96, the <strong>Chemsynth Tank</strong> (4432).</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>+0x64</td><td>not traced (probably the chemical&#39;s item id)</td></tr><tr><td>u32</td><td>+0xc</td><td>not traced</td></tr></tbody></table><p>Unusually, these two values are read <strong>only from a server</strong>; the client&#39;s own saved copy has no bytes.</p><p><small>Read by <code>0x15ce080</code>.</small></p><h2 id="0x36" tabindex="-1">0x36 Storage box <a class="header-anchor" href="#0x36" aria-label="Permalink to &quot;0x36 Storage box {#0x36}&quot;">​</a></h2><p>Item action type 97: <strong>Untrade-a-Box</strong> (4516), <strong>Storage Box Xtreme</strong> Levels 1–3 (6286–6290), <strong>Dynasty Vase</strong> (10584).</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u16 len + bytes</td><td>+0x10</td><td>not traced (the stored items aren&#39;t in the tile data)</td></tr></tbody></table><p><small>Read by <code>0x15ce080</code>.</small></p><h2 id="0x37" tabindex="-1">0x37 Oven <a class="header-anchor" href="#0x37" aria-label="Permalink to &quot;0x37 Oven {#0x37}&quot;">​</a></h2><p>Item type 98 (<code>ITEM_TYPE_OVEN</code>): Commercial Oven, Home Oven, Master Chef&#39;s Oven, Replicator, Taco Truck Oven. What is in the oven, the heat, and how long it has cooked.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>heat</td><td>0 off, 1 low, 2 medium, 3 high (the description shows &quot;Cooking on Low/Medium/High&quot;); 0 = no description</td></tr><tr><td>u32</td><td>n</td><td>number of u32 values that follow (2 per ingredient)</td></tr><tr><td>n × u32</td><td>ingredients</td><td>pairs of (item id, heat received so far)</td></tr><tr><td>u32</td><td>timer</td><td>seconds counted since the last update (the client adds to it every frame)</td></tr><tr><td>u64</td><td>started</td><td>only if world version &gt; 13: a Unix time; the description adds &quot;Elapsed Sec:&quot; since then</td></tr></tbody></table><p>Only sent this way <strong>from the server</strong>. In the client&#39;s own save format (<code>fromServer</code> false) the type has no data.</p><ul><li>Every update the client adds <code>heat × seconds</code> to the second value of each pair, so cooking goes on between server updates (<code>0x15d0b24</code>).</li><li>The description (<code>0x15b5234</code>) lists each ingredient with a doneness word chosen by comparing its value with the item&#39;s cook time from items.dat (item+0x4c, -1 = not cookable): Raw, Cold, Uncooked, Underdone, Cooked, Perfect, Well-Done, Overcooked, Burnt. Salt, Pepper, Sugar (4568, 4570, 4572) and item 726 are left out.</li><li>With heat &gt; 0 the oven is drawn with its &quot;lit&quot; frame, and the nearest lit oven plays the item&#39;s sound (<code>0x11a6a9c</code>).</li></ul><p><small>Read by <code>0x15ce080</code> (case 0x37); used by <code>0x15d0b24</code>, <code>0x15b5234</code>, <code>0x11a6a9c</code>.</small></p><h2 id="0x38" tabindex="-1">0x38 Audio Rack <a class="header-anchor" href="#0x38" aria-label="Permalink to &quot;0x38 Audio Rack {#0x38}&quot;">​</a></h2><p>Item type 99 (<code>ITEM_TYPE_SUPER_MUSIC</code>): Audio Gear, Audio Rack. A short tune that plays when you walk past.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u16 len + bytes</td><td>notes</td><td>the tune, see below</td></tr><tr><td>u32</td><td>volume</td><td>sound volume in percent (played at <code>volume / 100</code>); 0 or less = silent, not drawn as active</td></tr></tbody></table><p>The notes are read 3 characters at a time: an instrument letter, a note, and an accidental.</p><ul><li>Instrument: <code>B</code> bass, <code>D</code> drum, <code>E</code> electric guitar, <code>F</code> flute, <code>G</code> Spanish guitar, <code>L</code> lyre, <code>P</code> piano, <code>S</code> sax, <code>T</code> Mexican trumpet, <code>V</code> violin (the letters the parser accepts; the file each one plays is probably the instrument it starts with). A space is a rest (one character).</li><li>Note: <code>a</code>–<code>g</code> or <code>A</code>–<code>G</code> (the two cases are probably two octaves).</li><li>Accidental: <code>#</code> sharp, <code>b</code> flat, anything else natural. Parsing stops at the first character that doesn&#39;t fit. The sounds are <code>audio/notes/&lt;instrument&gt;_&lt;n&gt;.wav</code>.</li></ul><p><small>Read by <code>0x15ce080</code> (case 0x38); used by <code>0x11a50bc</code>, <code>0x11a497c</code>.</small></p><h2 id="0x39" tabindex="-1">0x39 Geiger Charger <a class="header-anchor" href="#0x39" aria-label="Permalink to &quot;0x39 Geiger Charger {#0x39}&quot;">​</a></h2><p>Item type 100 (<code>ITEM_TYPE_GEIGERCHARGE</code>): Geiger Charger.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>timer</td><td>seconds counted so far; the client keeps adding the elapsed seconds every update (probably the charging time)</td></tr></tbody></table><p><small>Read by <code>0x15ce080</code> (case 0x39, shared code with types 0x0f/0x1b/0x26/0x27/0x32); timer in <code>0x15d0b24</code>.</small></p><h2 id="0x3a" tabindex="-1">0x3a Adventure Begins <a class="header-anchor" href="#0x3a" aria-label="Permalink to &quot;0x3a Adventure Begins {#0x3a}&quot;">​</a></h2><p>Item type 101 (<code>ITEM_TYPE_ADVENTURE_RESET</code>): The Adventure Begins.</p><p><strong>From the server: no data.</strong> The fields exist only in the client&#39;s own save format (<code>fromServer</code> false): u8, u32, then a u16-length string.</p><p><small>Read by <code>0x15ce080</code> (case 0x3a).</small></p><h2 id="0x3b" tabindex="-1">0x3b Tomb Robber <a class="header-anchor" href="#0x3b" aria-label="Permalink to &quot;0x3b Tomb Robber {#0x3b}&quot;">​</a></h2><p>Item type 102 (<code>ITEM_TYPE_TOMB_ROBBER</code>): Tomb Robber.</p><p><strong>From the server: no data.</strong> In the client&#39;s own save format (<code>fromServer</code> false) it holds two u16-length strings and a u8.</p><p><small>Read by <code>0x15ce080</code> (case 0x3b).</small></p><h2 id="0x3c" tabindex="-1">0x3c Faction block <a class="header-anchor" href="#0x3c" aria-label="Permalink to &quot;0x3c Faction block {#0x3c}&quot;">​</a></h2><p>Item types 103–106 (<code>ITEM_TYPE_FACTION</code>, <code>RED_FACTION</code>, <code>GREEN_FACTION</code>, <code>BLUE_FACTION</code>): Balloon-O-Matic, Team Entrance - Punch, Team Entrance - Grow, Team Entrance - Build.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>value</td><td>not traced</td></tr><tr><td>u8</td><td>faction</td><td>0 Balloon-O-Matic, 1 punch, 2 grow, 3 build (the client sets it from the item type when the block is placed)</td></tr></tbody></table><p>For the Balloon-O-Matic (item type 103) the faction byte is added to the sprite frame, so it shows the team colour (<code>0x11a6a9c</code>).</p><p><small>Read by <code>0x15ce080</code> (case 0x3c); used by <code>0x11a6a9c</code>.</small></p><h2 id="0x3d" tabindex="-1">0x3d Training Port <a class="header-anchor" href="#0x3d" aria-label="Permalink to &quot;0x3d Training Port {#0x3d}&quot;">​</a></h2><p>Item type 109 (<code>ITEM_TYPE_FISHGOTCHI_TANK</code>): Training Port (5530). A fish being trained.</p><p>The data is read into a sub-object that the client creates only when the foreground&#39;s item type is 109. If the tile&#39;s foreground isn&#39;t a Training Port, <strong>nothing is read</strong> and the rest of the world is parsed from the wrong offset.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>size</td><td>the fish&#39;s size, passed with the fish id when the fish is drawn swimming in the port (as the pounds value of a Fish Tank fish)</td></tr><tr><td>u8</td><td>?</td><td>not traced</td></tr><tr><td>u8</td><td>done</td><td>1 = training finished: the timer stops and the fish swims differently</td></tr><tr><td>u32</td><td>fish</td><td>the fish&#39;s item id; 0 = empty port (the client redraws the fish when it changes between 0 and not 0)</td></tr><tr><td>u32</td><td>?</td><td>not traced</td></tr><tr><td>u32</td><td>remaining</td><td>counts down by <code>rate</code> per second</td></tr><tr><td>u32</td><td>progress</td><td>goes up once each time <code>remaining</code> runs out (one step per <code>rate</code> units)</td></tr><tr><td>u32</td><td>?</td><td>when it changes and isn&#39;t 0, the client rebuilds the fish (probably its level or look)</td></tr><tr><td>u32</td><td>rate</td><td>units per second (see above)</td></tr><tr><td>u32</td><td>target</td><td>when <code>progress</code> passes it, <code>done</code> is set</td></tr><tr><td>u8</td><td>paused</td><td>1 = the timer doesn&#39;t run</td></tr></tbody></table><p><small>Read by <code>0x15ce080</code> (case 0x3d); timer in <code>0x15d0b24</code>; fish drawing <code>0x1844e18</code>, <code>0x1845364</code>; packet 0x05 handler in <code>0x1373e20</code>.</small></p><h2 id="0x3e" tabindex="-1">0x3e Item Sucker (MAGPLANT) <a class="header-anchor" href="#0x3e" aria-label="Permalink to &quot;0x3e Item Sucker (MAGPLANT) {#0x3e}&quot;">​</a></h2><p>Item type 111 (<code>ITEM_TYPE_ITEM_SUCKER</code>): MAGPLANT 5000, Gaia&#39;s Beacon, Unstable Tesseract. It collects one kind of item.</p><p>The first four fields go into a sub-object the client creates only when the foreground&#39;s item type is 111. Otherwise <strong>nothing is read</strong> for them.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>item</td><td>the item it collects; drawn as an icon on the block; 0 = not set</td></tr><tr><td>u32</td><td>count</td><td>how many it holds; the block blinks when <code>count</code> reaches capacity − 25</td></tr><tr><td>u8</td><td>?</td><td>not traced</td></tr><tr><td>u8</td><td>look</td><td>picks one of two frames for the &quot;has an item&quot; overlay (probably on/off)</td></tr><tr><td>u32</td><td>capacity</td><td>only from the server: the maximum count. The client writes the item&#39;s own limit here when it saves</td></tr></tbody></table><p><small>Read by <code>0x15ce080</code> (case 0x3e); drawn in <code>0x11a9ee4</code>; world list in <code>0x15af7b8</code>.</small></p><h2 id="0x3f" tabindex="-1">0x3f Robot <a class="header-anchor" href="#0x3f" aria-label="Permalink to &quot;0x3f Robot {#0x3f}&quot;">​</a></h2><p>Item type 113 (<code>ITEM_TYPE_ROBOT</code>): ShockBot, SpikeBot, ShooterBot, FlameBot, SearBot (all levels). The bot&#39;s program, a list of command blocks.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>n</td><td>number of commands</td></tr><tr><td>n × entry</td><td>commands</td><td>see below</td></tr><tr><td>u32</td><td>?</td><td>not traced (the client has no timer for this type)</td></tr><tr><td>u32</td><td>state</td><td>1 or more: the bot is drawn with its active frame (+2)</td></tr></tbody></table><p>Each entry, in order:</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>the command block&#39;s item id. The robot (<code>0x1943d38</code>) turns each into a move: the item&#39;s flags (item+0x64) pick the command kind (&quot;Adding Command&quot;, &quot;Adding Mirror Command&quot;)</td></tr><tr><td>u8</td><td>not traced</td></tr><tr><td>u32</td><td>not traced</td></tr><tr><td>u32</td><td>not traced</td></tr><tr><td>u16 len + bytes</td><td>a string, not traced</td></tr></tbody></table><p><small>Read by <code>0x15ce080</code> (case 0x3f); robots built in <code>0x1943950</code>/<code>0x1943d38</code>; frame in <code>0x11a6a9c</code>.</small></p><h2 id="0x40" tabindex="-1">0x40 Lucky Token <a class="header-anchor" href="#0x40" aria-label="Permalink to &quot;0x40 Lucky Token {#0x40}&quot;">​</a></h2><p>Item type 115 (<code>ITEM_TYPE_LUCKY_TICKET</code>): Lucky Token and the Year of the … Lucky Tokens.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u16 len + bytes</td><td>text</td><td>not traced (probably the owner&#39;s name or a message)</td></tr></tbody></table><p><small>Read by <code>0x15ce080</code> (case 0x40, same code as the end of 0x0b).</small></p><h2 id="0x41" tabindex="-1">0x41 (no data) <a class="header-anchor" href="#0x41" aria-label="Permalink to &quot;0x41 (no data) {#0x41}&quot;">​</a></h2><p>Not a case in the 5.60 parser, so the type byte is followed by nothing. The client gives this type to a new tile extra when the item&#39;s &quot;has extra&quot; flag (item+0x65 bit 1) is set but its item type maps to no other extra type.</p><p><small>Default in <code>0x15ce080</code>; set in <code>0x15aef40</code>.</small></p><h2 id="0x42" tabindex="-1">0x42 GrowScan 9000 <a class="header-anchor" href="#0x42" aria-label="Permalink to &quot;0x42 GrowScan 9000 {#0x42}&quot;">​</a></h2><p>Item type 116 (<code>ITEM_TYPE_STATS_BLOCK</code>): GrowScan 9000.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u8</td><td>flags</td><td>not traced</td></tr></tbody></table><p><small>Read by <code>0x15ce080</code> (case 0x42, the same byte as the end of type 0x01).</small></p><h2 id="0x43" tabindex="-1">0x43 Containment Field Power Node <a class="header-anchor" href="#0x43" aria-label="Permalink to &quot;0x43 Containment Field Power Node {#0x43}&quot;">​</a></h2><p>Item type 117 (<code>ITEM_TYPE_FIELD_NODE</code>): Containment Field Power Node.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>value</td><td>not traced</td></tr><tr><td>u32</td><td>n</td><td>number of values</td></tr><tr><td>n × u32</td><td>list</td><td>not traced (probably the linked nodes)</td></tr></tbody></table><p><small>Read by <code>0x15ce080</code> (case 0x43).</small></p><h2 id="0x44" tabindex="-1">0x44 Spirit Board <a class="header-anchor" href="#0x44" aria-label="Permalink to &quot;0x44 Spirit Board {#0x44}&quot;">​</a></h2><p>Item type 118 (<code>ITEM_TYPE_OUIJA_BOARD</code>): Spirit Board, Dark Spirit Board.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>value</td><td>not traced</td></tr><tr><td>u16 len + bytes</td><td>text 1</td><td>not traced</td></tr><tr><td>u16 len + bytes</td><td>text 2</td><td>not traced</td></tr><tr><td>u32</td><td>n</td><td>number of values</td></tr><tr><td>n × u32</td><td>list</td><td>not traced</td></tr></tbody></table><p><small>Read by <code>0x15ce080</code> (case 0x44).</small></p><h2 id="0x45" tabindex="-1">0x45 Tesseract Manipulator <a class="header-anchor" href="#0x45" aria-label="Permalink to &quot;0x45 Tesseract Manipulator {#0x45}&quot;">​</a></h2><p>Item type 123 (<code>ITEM_TYPE_AUTO_ACTION_BREAK</code>): Tesseract Manipulator. It breaks blocks by itself.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>fuel</td><td>probably the gems it has left: with 0 an extra &quot;empty&quot; overlay frame is drawn on the block</td></tr><tr><td>u32</td><td>?</td><td>not traced</td></tr><tr><td>u32</td><td>target</td><td>the item it works on; drawn as an icon on the block, 0 = not set</td></tr><tr><td>u32</td><td>on</td><td>only if world version &gt; 7: not 0 = running, the block animates</td></tr></tbody></table><p><small>Read by <code>0x15ce080</code> (case 0x45, shared with 0x46); drawn in <code>0x11a9ee4</code>.</small></p><h2 id="0x46" tabindex="-1">0x46 Heart of Gaia <a class="header-anchor" href="#0x46" aria-label="Permalink to &quot;0x46 Heart of Gaia {#0x46}&quot;">​</a></h2><p>Item type 124 (<code>ITEM_TYPE_AUTO_ACTION_HARVEST</code>): Heart of Gaia. It harvests trees by itself.</p><p>Same layout and meanings as <a href="#0x45">0x45</a>.</p><p><small>Read by <code>0x15ce080</code> (case 0x46).</small></p><h2 id="0x47" tabindex="-1">0x47 Techno-Organic Engine <a class="header-anchor" href="#0x47" aria-label="Permalink to &quot;0x47 Techno-Organic Engine {#0x47}&quot;">​</a></h2><p>Item type 125 (<code>ITEM_TYPE_AUTO_ACTION_HARVEST_SUCK</code>): Techno-Organic Engine. It harvests and collects.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>fuel</td><td>as in <a href="#0x45">0x45</a></td></tr><tr><td>u32</td><td>?</td><td>not traced</td></tr><tr><td>u32</td><td>target</td><td>the item it works on</td></tr><tr><td>u32</td><td>on</td><td>only if world version &gt; 7: not 0 = running</td></tr><tr><td>u32</td><td>item</td><td>storage sub-object: the item it holds (only read if the foreground&#39;s item type is 125, like <a href="#0x3e">0x3e</a>)</td></tr><tr><td>u32</td><td>count</td><td>storage: how many</td></tr><tr><td>u8</td><td>?</td><td>storage: not traced</td></tr><tr><td>u8</td><td>look</td><td>storage: frame choice</td></tr><tr><td>u32</td><td>offset</td><td>added to <code>target</code> to get the icon drawn on the block (probably 1 = show the target&#39;s seed)</td></tr><tr><td>u32</td><td>?</td><td>not traced</td></tr></tbody></table><p>If the foreground isn&#39;t item type 125, the four storage fields are <strong>not read</strong> and the parse goes out of step.</p><p><small>Read by <code>0x15ce080</code> (case 0x47); drawn in <code>0x11a9ee4</code>.</small></p><h2 id="0x48" tabindex="-1">0x48 Storm Cloud <a class="header-anchor" href="#0x48" aria-label="Permalink to &quot;0x48 Storm Cloud {#0x48}&quot;">​</a></h2><p>Item type 126 (<code>ITEM_TYPE_LIGHTNING_CLOUD</code>): Storm Cloud.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>?</td><td>not traced (0 when placed)</td></tr><tr><td>u32</td><td>?</td><td>not traced (1 when placed)</td></tr><tr><td>u32</td><td>?</td><td>not traced (0 when placed)</td></tr></tbody></table><p><small>Read by <code>0x15ce080</code> (case 0x48); defaults from <code>0x15d1014</code>.</small></p><h2 id="0x49" tabindex="-1">0x49 Phased block <a class="header-anchor" href="#0x49" aria-label="Permalink to &quot;0x49 Phased block {#0x49}&quot;">​</a></h2><p>Item type 127 (<code>ITEM_TYPE_PHASED_BLOCK</code>): Cracked Stone Slab, Dunking Bucket.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>value</td><td>not traced</td></tr></tbody></table><p><small>Read by <code>0x15ce080</code> (case 0x49, same code as 0x28/0x29/0x4e/0x4f).</small></p><h2 id="0x4a" tabindex="-1">0x4a Safe Vault <a class="header-anchor" href="#0x4a" aria-label="Permalink to &quot;0x4a Safe Vault {#0x4a}&quot;">​</a></h2><p>Item type 130 (<code>ITEM_TYPE_PASSWORD_STORAGE</code>): Safe Vault.</p><p><strong>From the server: no data.</strong> In the client&#39;s own save format (<code>fromServer</code> false) it holds three u16-length strings. The server keeps the password and contents to itself.</p><p><small>Read by <code>0x15ce080</code> (case 0x4a).</small></p><h2 id="0x4b" tabindex="-1">0x4b Angelic Counting Cloud <a class="header-anchor" href="#0x4b" aria-label="Permalink to &quot;0x4b Angelic Counting Cloud {#0x4b}&quot;">​</a></h2><p>Item type 131 (<code>ITEM_TYPE_PHASED_BLOCK_2</code> in the client&#39;s name table): Angelic Counting Cloud (9346).</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>number</td><td>added to the sprite frame, so it picks the digit the cloud shows</td></tr><tr><td>u16 len + bytes</td><td>text</td><td>not traced</td></tr></tbody></table><p><small>Read by <code>0x15ce080</code> (case 0x4b); frame in <code>0x11a6a9c</code>.</small></p><h2 id="0x4c" tabindex="-1">0x4c PvE NPC <a class="header-anchor" href="#0x4c" aria-label="Permalink to &quot;0x4c PvE NPC {#0x4c}&quot;">​</a></h2><p>Item type 133 (<code>ITEM_TYPE_PVE_NPC</code>). No item in the current items.dat has this type. The data is read into a 0x370-byte PvE object that the client creates only when the foreground&#39;s item type is 133; otherwise <strong>nothing is read</strong>.</p><p>Three entries (probably the NPC&#39;s three forms, see <a href="/gtps-guide/packets/29-pve-npc">PVE_NPC (0x29)</a>), each:</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Meaning</th></tr></thead><tbody><tr><td>25 × 4 bytes</td><td>stats. Values 1, 2, 3, 8, 11, 13, 21 and 22 (counting from 0) are floats; 5, 6, 10, 14, 19 and 24 are read as 0/1 flags; the rest are ints. Meanings not traced</td></tr><tr><td>u32 n</td><td>number of pairs</td></tr><tr><td>n × (u32, u32)</td><td>pairs, not traced</td></tr></tbody></table><p><small>Read by <code>0x15ce080</code> (case 0x4c), entries from <code>0x14b7680</code>.</small></p><h2 id="0x4d" tabindex="-1">0x4d Infinity Weather Machine <a class="header-anchor" href="#0x4d" aria-label="Permalink to &quot;0x4d Infinity Weather Machine {#0x4d}&quot;">​</a></h2><p>Item type 134 (<code>ITEM_TYPE_INFINITY_WEATHER_MACHINE</code>): Infinity Weather Machine.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>value</td><td>not traced (probably the time per weather)</td></tr><tr><td>u32</td><td>n</td><td>number of values</td></tr><tr><td>n × u32</td><td>list</td><td>probably the weathers it cycles through</td></tr></tbody></table><p>The block animates while its weather is the world&#39;s current weather (as the other weather machines do).</p><p><small>Read by <code>0x15ce080</code> (case 0x4d, the end of 0x2c&#39;s code); frame in <code>0x11a6a9c</code>.</small></p><h2 id="0x4e" tabindex="-1">0x4e Completionist <a class="header-anchor" href="#0x4e" aria-label="Permalink to &quot;0x4e Completionist {#0x4e}&quot;">​</a></h2><p>Item type 137 (<code>ITEM_TYPE_COMPLETIONIST</code>). No item in the current items.dat has this type.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>value</td><td>not traced</td></tr></tbody></table><p><small>Read by <code>0x15ce080</code> (case 0x4e).</small></p><h2 id="0x4f" tabindex="-1">0x4f Feeding block <a class="header-anchor" href="#0x4f" aria-label="Permalink to &quot;0x4f Feeding block {#0x4f}&quot;">​</a></h2><p>Item type 140 (<code>ITEM_TYPE_FEEDING_BLOCK</code>): Pineapple Guzzler.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>value</td><td>not traced (probably how much it has been fed)</td></tr></tbody></table><p><small>Read by <code>0x15ce080</code> (case 0x4f).</small></p><h2 id="0x50" tabindex="-1">0x50 Kranken&#39;s block <a class="header-anchor" href="#0x50" aria-label="Permalink to &quot;0x50 Kranken&#39;s block {#0x50}&quot;">​</a></h2><p>Item type 141 (<code>ITEM_TYPE_KRANKENS_BLOCK</code>): Kranken&#39;s Galactic Block and Krankens Pattern 1–10.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>value</td><td>not traced (0 when placed)</td></tr><tr><td>u32</td><td>color</td><td>the block is drawn tinted with this colour (packed RGBA, <code>0xffffffff</code> = no tint, the default)</td></tr></tbody></table><p><small>Read by <code>0x15ce080</code> (case 0x50); drawn in <code>0x11a9ee4</code>.</small></p><h2 id="0x51" tabindex="-1">0x51 Friends Entrance <a class="header-anchor" href="#0x51" aria-label="Permalink to &quot;0x51 Friends Entrance {#0x51}&quot;">​</a></h2><p>Item type 142 (<code>ITEM_TYPE_FRIENDS_ENTRANCE</code>): Friends Entrance.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>?</td><td>not traced (0 when placed)</td></tr><tr><td>u32</td><td>?</td><td>not traced (1 when placed)</td></tr></tbody></table><p><small>Read by <code>0x15ce080</code> (case 0x51).</small></p><h2 id="0x52" tabindex="-1">0x52 (no data) <a class="header-anchor" href="#0x52" aria-label="Permalink to &quot;0x52 (no data) {#0x52}&quot;">​</a></h2><p>Accepted by the parser (only types above 0x52 log &quot;Bad type of %d detected in tileextra&quot;) but there is no case for it, so nothing follows the type byte.</p><p><small>Default in <code>0x15ce080</code>.</small></p>',373)])])}const p=e(r,[["render",n]]);export{b as __pageData,p as default};
